const int BUTTON = 2;

void setup() {
    Serial.begin(115200);
    pinMode(BUTTON, INPUT_PULLUP);   // knappen mellan pinne och GND
}

void loop() {
    if (digitalRead(BUTTON) == LOW) {   // intryckt = LOW med pull-up
        Serial.println("Knappen trycktes");
        delay(200);                     // enkel avstudsning
    }
}
